use vstd::prelude::*;

verus! {
    // Copy a vector of u64s, preserving length and contents.
    fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
        requires
            // the input's length is at most 100
            a.len() <= 100,
        ensures
            // the result has the same length
            b.len() == a.len(),
        ensures
            // and for every index i in range, the elements agree
            forall |i: usize| i < a.len() ==> b[i] == a[i],
    {
        let mut b: Vec<u64> = Vec::new();
        let mut i: usize = 0;
        // Loop to push each element of `a` onto `b`
        while i < a.len()
            invariant
                // we only advance from 0 up to a.len()
                i <= a.len(),
                // b has exactly i elements so far
                b.len() == i,
                // and those i elements match the prefix of a
                forall |j: usize| j < i ==> b[j] == a[j],
            decreases
                // measure ensures termination
                a.len() - i,
        {
            // read the i-th element
            let x = a[i];
            // push it on to b
            b.push(x);
            proof {
                // after the push, b.len() should be i+1
                assert(b.len() == i + 1);
                // and the newly pushed element is x == a[i]
                assert(b[i] == x);
            }
            // advance the index
            i = i + 1;
        }
        b
    }
}

